<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Покрытие паспортов — ПрофиСпорт</title>
<style>
:root{--y:#f2c94c;--bg:#f5f5f3;--tx:#202124;--muted:#747a80;--line:#e3e3df;--green:#187a3c;--red:#a33e35;--page:1180px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:14px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}.top{position:sticky;top:0;z-index:20;background:#34393e;color:#fff}.topin{max-width:var(--page);min-height:62px;margin:auto;padding:0 14px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:20px;font-weight:950}.brand span{color:var(--y)}.back{color:#fff;text-decoration:none;padding:9px 12px;border:1px solid #ffffff25;border-radius:10px}main{max-width:var(--page);margin:auto;padding:20px 14px 70px}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:14px}.head h1{margin:0;font-size:31px}.head p{margin:5px 0 0;color:var(--muted)}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button{border:0;border-radius:10px;padding:10px 13px;font-weight:900;cursor:pointer}.actions .secondary{background:#e7e8e5}.actions .primary{background:var(--y)}.stats{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:9px;margin:16px 0}.stat{padding:13px;border:1px solid var(--line);border-radius:14px;background:#fff}.stat small{display:block;color:var(--muted)}.stat b{display:block;margin-top:4px;font-size:21px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.panel{min-width:0;padding:16px;border:1px solid var(--line);border-radius:17px;background:#fff}.panel h2{margin:0 0 3px}.panel>p{margin:0 0 12px;color:var(--muted)}.list{display:grid;gap:7px;max-height:650px;overflow:auto}.row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:10px;border:1px solid #e8e6df;border-radius:11px;background:#faf9f5}.row b,.row span,.row small{display:block}.row small{margin-top:3px;color:var(--muted)}.badge{height:max-content;padding:5px 8px;border-radius:999px;font-size:10px;font-weight:900}.badge.ok{background:#e5f5e9;color:var(--green)}.badge.wait{background:#fff0cb;color:#765a00}.badge.conflict{background:#f8e5e2;color:var(--red)}.row .reason{margin-top:6px;padding:7px 8px;border-radius:8px;background:#fff0ee;color:#7f332b}.row a{color:inherit}.source{display:inline-flex;margin-top:5px;color:inherit;font-size:11px}.notice{min-height:22px;margin:10px 0;color:var(--muted)}.empty{padding:14px;border:1px dashed #d8d4ca;border-radius:12px;color:var(--muted)}
@media(max-width:1050px){.grid{grid-template-columns:1fr 1fr}.panel.conflictsPanel{grid-column:1/-1}}@media(max-width:900px){.stats{grid-template-columns:repeat(3,minmax(0,1fr))}.grid{grid-template-columns:1fr}.panel.conflictsPanel{grid-column:auto}}@media(max-width:560px){.head{display:grid}.actions{display:grid}.actions button{width:100%}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style></head><body><header class="top"><div class="topin"><div class="brand">Профи<span>Спорт</span> · Паспорта</div><a class="back" href="index.php">← Админка</a></div></header>
<main><div class="head"><div><h1>Покрытие паспортов техники</h1><p>Только точные совпадения модели, года и диаметра колёс получают официальную комплектацию автоматически.</p></div><div class="actions"><button id="rescan" class="secondary" type="button">Обновить очередь</button><button id="apply" class="primary" type="button">Применить подтверждённый реестр</button></div></div><div id="notice" class="notice"></div><section id="stats" class="stats"></section><div class="grid"><section class="panel"><h2>Подтверждено</h2><p>Эти товары совпали с одной конкретной официальной спецификацией.</p><div id="matched" class="list"></div></section><section class="panel conflictsPanel"><h2>Конфликт источников</h2><p>Автозаполнение заблокировано: источники расходятся, нужна проверка фактической комплектации.</p><div id="conflicts" class="list"></div></section><section class="panel"><h2>Требует исследования</h2><p>Ничего не подставляется автоматически, пока точное совпадение не подтверждено.</p><div id="unmatched" class="list"></div></section></div></main>
<script>
let csrf='';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),fmt=n=>Number(n||0).toLocaleString('ru-RU');
function row(x,mode){const ok=mode==='ok',conflict=mode==='conflict';return '<article class="row"><div><b>'+esc(x.title)+'</b><small>'+esc([x.brand,x.model].filter(Boolean).join(' · ')||'Бренд/модель из базы не заполнены')+'</small>'+(x.match_key?'<small>'+(conflict?'Конфликт: ':'Профиль: ')+esc(x.match_key)+'</small>':'')+(conflict&&x.note?'<div class="reason">'+esc(x.note)+(x.reference_url?' <a href="'+esc(x.reference_url)+'" target="_blank" rel="noopener">Официальный источник →</a>':'')+'</div>':'')+'</div><span class="badge '+(ok?'ok':conflict?'conflict':'wait')+'">'+(ok?'Проверено':conflict?'Конфликт':'Исследовать')+'</span></article>'}
function render(s){$('#stats').innerHTML='<div class="stat"><small>Профилей в реестре</small><b>'+fmt(s.registry_profiles)+'</b></div><div class="stat"><small>Велосипедов в каталоге</small><b>'+fmt(s.catalog_bicycles)+'</b></div><div class="stat"><small>Совпало</small><b>'+fmt(s.catalog_matched)+'</b></div><div class="stat"><small>Конфликтов</small><b>'+fmt(s.catalog_conflicts)+'</b></div><div class="stat"><small>Не подтверждено</small><b>'+fmt(s.catalog_unmatched)+'</b></div><div class="stat"><small>Велосипедов клиентов</small><b>'+fmt(s.customer_bicycles)+'</b></div><div class="stat"><small>Паспортов с реестром</small><b>'+fmt(s.customer_bicycles_verified)+'</b></div>';$('#matched').innerHTML=(s.matched||[]).map(x=>row(x,'ok')).join('')||'<div class="empty">Подтверждённых совпадений в текущем каталоге пока нет.</div>';$('#conflicts').innerHTML=(s.conflicts||[]).map(x=>row(x,'conflict')).join('')||'<div class="empty">Активных конфликтов источников нет.</div>';$('#unmatched').innerHTML=(s.unmatched||[]).map(x=>row(x,'wait')).join('')||'<div class="empty">Все остальные найденные велосипеды уже разобраны.</div>'}
async function load(){const r=await fetch('../api/vehicle-spec-admin.php',{cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'load_failed');csrf=j.csrf||csrf;render(j.summary)}
async function act(action){const button=action==='apply_registry'?$('#apply'):$('#rescan'),n=$('#notice');button.disabled=true;n.textContent=action==='apply_registry'?'Применяю подтверждённые спецификации к существующим паспортам…':'Пересчитываю покрытие текущего каталога…';try{const r=await fetch('../api/vehicle-spec-admin.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({action})}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'action_failed');render(j.summary);n.textContent=action==='apply_registry'?'Готово: велосипедов сопоставлено '+fmt(j.applied?.vehicles_matched)+', компонентов добавлено '+fmt(j.applied?.components_inserted)+', обновлено '+fmt(j.applied?.components_updated)+'.':'Очередь обновлена.'}catch(e){n.textContent='Не удалось выполнить действие.'}finally{button.disabled=false}}
$('#rescan').onclick=()=>act('rescan');$('#apply').onclick=()=>{if(confirm('Применить только подтверждённые профили реестра ко всем существующим паспортам? Ручные и сервисные данные не перезаписываются.'))act('apply_registry')};load().catch(()=>{$('#notice').textContent='Не удалось загрузить покрытие паспортов.'});
</script></body></html>